-- DISPO SP Leyment V5 — execute in Supabase SQL editor
create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, first_name text not null default '', last_name text not null default '', phone text default '', is_admin boolean not null default false, active boolean not null default true, created_at timestamptz not null default now());
create table public.availability (user_id uuid not null references public.profiles(id) on delete cascade, week_start date not null, slot text not null check(slot in ('nights','weekend')), status text not null check(status in ('yes','no','unknown')), updated_at timestamptz not null default now(), primary key(user_id,week_start,slot));
create table public.assignments (id uuid primary key default gen_random_uuid(), week_start date not null, slot text not null check(slot in ('nights','weekend')), user_id uuid references public.profiles(id), state text not null default 'confirmed' check(state in ('confirmed','vacant')), created_at timestamptz not null default now(), unique(week_start,slot,user_id));
create table public.replacements (id uuid primary key default gen_random_uuid(), assignment_id uuid not null references public.assignments(id) on delete cascade, requester uuid not null references public.profiles(id), volunteer uuid references public.profiles(id), status text not null default 'open' check(status in ('open','offered','approved','closed')), created_at timestamptz not null default now());
create table public.drills (id uuid primary key default gen_random_uuid(), title text not null, starts_at timestamptz not null, details text default '', created_by uuid references public.profiles(id));
create table public.drill_rsvps (drill_id uuid not null references public.drills(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, status text not null check(status in ('yes','no','maybe')), primary key(drill_id,user_id));
create table public.notices (id uuid primary key default gen_random_uuid(), title text not null, body text not null, created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and is_admin and active)$$;
create or replace function public.is_active() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and active)$$;
create or replace function public.week_monday(d date) returns date language sql immutable as $$select (d - (extract(isodow from d)::int-1))::date$$;
-- A new account gets a profile, but is inactive until approved by admin.
create or replace function public.new_user_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,first_name,last_name,phone,active) values(new.id,coalesce(new.raw_user_meta_data->>'first_name',''),coalesce(new.raw_user_meta_data->>'last_name',''),coalesce(new.raw_user_meta_data->>'phone',''),false); return new; end$$;
create trigger auth_user_created after insert on auth.users for each row execute function public.new_user_profile();
alter table profiles enable row level security; alter table availability enable row level security; alter table assignments enable row level security; alter table replacements enable row level security; alter table drills enable row level security; alter table drill_rsvps enable row level security; alter table notices enable row level security;
create policy profiles_read on profiles for select to authenticated using(public.is_active());
create policy profiles_admin_update on profiles for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy availability_read on availability for select to authenticated using(public.is_active());
create policy availability_write on availability for insert to authenticated with check(public.is_active() and user_id=auth.uid());
create policy availability_update on availability for update to authenticated using(public.is_active() and user_id=auth.uid()) with check(user_id=auth.uid());
create policy assignments_read on assignments for select to authenticated using(public.is_active());
create policy replacements_read on replacements for select to authenticated using(public.is_active());
create policy drills_read on drills for select to authenticated using(public.is_active());
create policy drills_admin_insert on drills for insert to authenticated with check(public.is_admin());
create policy drills_admin_update on drills for update to authenticated using(public.is_admin());
create policy drills_admin_delete on drills for delete to authenticated using(public.is_admin());
create policy rsvps_read on drill_rsvps for select to authenticated using(public.is_active());
create policy rsvps_insert on drill_rsvps for insert to authenticated with check(public.is_active() and user_id=auth.uid());
create policy rsvps_update on drill_rsvps for update to authenticated using(public.is_active() and user_id=auth.uid());
create policy notices_read on notices for select to authenticated using(public.is_active());
-- Transactional RPC: members can only decline their own assigned slot; admins approve volunteers.
create or replace function public.decline_assignment(aid uuid) returns void language plpgsql security definer set search_path=public as $$declare a assignments%rowtype; begin if not is_active() then raise exception 'Accès refusé'; end if; select * into a from assignments where id=aid for update; if not found or a.user_id<>auth.uid() or a.state<>'confirmed' then raise exception 'Affectation non autorisée'; end if; if exists(select 1 from replacements where assignment_id=aid and status in ('open','offered')) then return; end if; insert into replacements(assignment_id,requester) values(aid,auth.uid()); insert into notices(title,body) values('Remplacement demandé','Un remplacement est demandé pour '||a.slot||' à partir du '||a.week_start); end$$;
create or replace function public.offer_replacement(rid uuid) returns void language plpgsql security definer set search_path=public as $$declare r replacements%rowtype; a assignments%rowtype; begin if not is_active() then raise exception 'Accès refusé'; end if; select * into r from replacements where id=rid for update; if not found or r.status<>'open' or r.requester=auth.uid() then raise exception 'Demande indisponible'; end if; select * into a from assignments where id=r.assignment_id; if exists(select 1 from availability where user_id=auth.uid() and week_start=a.week_start and slot=a.slot and status='no') then raise exception 'Vous êtes indisponible'; end if; if exists(select 1 from assignments where week_start=a.week_start and slot=a.slot and user_id=auth.uid() and state='confirmed') then raise exception 'Déjà affecté'; end if; update replacements set volunteer=auth.uid(),status='offered' where id=rid; insert into notices(title,body) values('Volontaire proposé','Une proposition de remplacement attend validation'); end$$;
create or replace function public.approve_replacement(rid uuid, accept boolean) returns void language plpgsql security definer set search_path=public as $$declare r replacements%rowtype; a assignments%rowtype; begin if not is_admin() then raise exception 'Réservé à l’administrateur'; end if; select * into r from replacements where id=rid for update; if not found or r.status<>'offered' then raise exception 'Demande non valide'; end if; select * into a from assignments where id=r.assignment_id for update; if accept then if exists(select 1 from assignments where week_start=a.week_start and slot=a.slot and user_id=r.volunteer and state='confirmed') then raise exception 'Déjà affecté'; end if; update assignments set user_id=r.volunteer where id=a.id; update replacements set status='approved' where id=rid; insert into notices(title,body) values('Remplacement validé','Le planning a été mis à jour'); else update replacements set status='open',volunteer=null where id=rid; end if; end$$;
-- Generate the following Monday's two slots; only explicitly available members eligible.
create or replace function public.generate_next_week() returns text language plpgsql security definer set search_path=public as $$declare w date; s text; n int; uid uuid; begin if not is_admin() then raise exception 'Réservé à l’administrateur'; end if; w:=week_monday((now() at time zone 'Europe/Paris')::date)+7; if exists(select 1 from assignments where week_start=w) then return 'Planning déjà généré'; end if; foreach s in array array['nights','weekend'] loop for n in 1..2 loop select p.id into uid from profiles p join availability av on av.user_id=p.id and av.week_start=w and av.slot=s and av.status='yes' where p.active and not exists(select 1 from assignments a where a.week_start=w and a.slot=s and a.user_id=p.id) order by (select count(*) from assignments x where x.user_id=p.id and x.state='confirmed' and x.week_start>=w-84), random() limit 1; insert into assignments(week_start,slot,user_id,state) values(w,s,uid,case when uid is null then 'vacant' else 'confirmed' end); uid:=null; end loop; end loop; insert into notices(title,body) values('Planning publié','Planning de la semaine du '||w||' généré'); return 'Planning généré pour '||w; end$$;
-- A server scheduler can invoke this safely without a user token via service role (not exposed in browser).
create or replace function public.generate_scheduled() returns text language plpgsql security definer set search_path=public as $$declare w date; s text; n int; uid uuid; begin w:=week_monday((now() at time zone 'Europe/Paris')::date)+7; if exists(select 1 from assignments where week_start=w) then return 'Déjà généré'; end if; foreach s in array array['nights','weekend'] loop for n in 1..2 loop select p.id into uid from profiles p join availability av on av.user_id=p.id and av.week_start=w and av.slot=s and av.status='yes' where p.active and not exists(select 1 from assignments a where a.week_start=w and a.slot=s and a.user_id=p.id) order by (select count(*) from assignments x where x.user_id=p.id and x.state='confirmed' and x.week_start>=w-84),random() limit 1; insert into assignments(week_start,slot,user_id,state) values(w,s,uid,case when uid is null then 'vacant' else 'confirmed' end); uid:=null; end loop; end loop; insert into notices(title,body) values('Planning publié','Planning de la semaine du '||w||' généré'); return 'Généré'; end$$;
revoke all on function public.generate_scheduled() from public,anon,authenticated;
-- Optional pg_cron: 18:00 Europe/Paris is 17:00 UTC in winter, 16:00 UTC in summer.
-- Use hourly checks at 16:00 and 17:00 UTC and gate on Paris local Thursday 18:00.
-- select cron.schedule('leyment-jeudi-18h','0 16,17 * * 4', $$select public.generate_scheduled() where extract(hour from now() at time zone 'Europe/Paris')=18$$);
